import org.formasaloido.*;import java.util.*;

public final class MathChecks {
 static int checks;static void check(boolean b,String s){checks++;if(!b)throw new AssertionError(s);}static void value(String s,String result){MathLesson m=new MathLesson(s);check(m.result.equals(result),s+" → "+m.result+", expected "+result);check(MathLesson.load(m.project()).result.equals(result),"Roundtrip "+s);check(!m.tokens.isEmpty()&&!m.steps.isEmpty()&&!m.rows.isEmpty(),"Navigation "+s);}
 static void reject(String s){try{new MathLesson(s);throw new AssertionError("Accepted "+s);}catch(IllegalArgumentException expected){checks++;}}
 public static void main(String[] args){
  check(MathSpeech.normalize("x^2 = 1/2").equals("equis elevado a dos igual a uno sobre dos"),"raw math speech");check(MathSpeech.normalize("−0.50 × 2 ≈ -1").equals("menos cero coma cinco cero por dos aproximadamente menos uno"),"decimal precision and Unicode operators");check(MathSpeech.normalize("Sin solución. Texto sin cambios.").equals("Sin solución. Texto sin cambios."),"ordinary prose preserved");check(MathSpeech.normalize("sin(30) ≤ 50%").equals("seno de abre paréntesis treinta cierra paréntesis menor o igual que cincuenta por ciento"),"functions and comparison");
  value("28 + 17","45");value("1000 - 1","999");value("1 - 1000","-999");value("23*14","322");value("125 / 4","125/4");value("1/2 + 1/3","5/6");value("1,25 + 2.5","15/4");value("(3+2)^2","25");value("-2^2","-4");value("(-2)^2","4");value("2^3^2","512");value("2^-3","1/8");value("−3 × 2","-6");
  value("2x + 3 = 11","x = 4");value("3*(x-2)=x+4","x = 5");value("x/2=1/3","x = 2/3");value("x=x","Infinitas soluciones");value("x=x+1","Sin solución");value("(x+2)*(x-3)","x^2 - x - 6");value("(x+1)^3","x^3 + 3 * x^2 + 3 * x + 1");value("-x^2+2x-x","-x^2 + x");
  value("sin(30)","≈ 0.5");value("cos(60)","≈ 0.5");value("tan(45)","≈ 1");value("rad: sin(pi/2)","≈ 1");value("sin(30)^2+cos(30)^2","≈ 1");value("sqrt(4)","≈ 2");
  for(String bad:new String[]{"","1/0","0^0","2^13","(2+3","1 +","1;foo()","tan(90)","sqrt(-1)","sin(x)","x^5","1/x","x^2=4","x==1","x+y","rad: sin(1/0)"})reject(bad);
  Random random=new Random(20261020);for(int i=0;i<1600;i++){int a=random.nextInt(1000000),b=random.nextInt(999999)+1;value(a+"+"+b,Long.toString((long)a+b));value(a+"-"+b,Long.toString((long)a-b));value(a+"*"+b,Long.toString((long)a*b));}
  for(int i=1;i<=100;i++){value(i+"x + "+(i*2)+" = "+(i*5),"x = 3");}
  check(new MathLesson("28+17").steps.get(0).contains("lleva una"),"Carry announced");check(new MathLesson("1000-1").steps.size()>=5,"Borrow chain retained");check(new MathLesson("125/4").script().contains("Resto: uno"),"Division remainder");check(new MathLesson("2x+3=11").script().contains("Comprobación"),"Equation verification");
  check(new MathLesson("1/2+1/3").script().contains("denominador común seis"),"Fraction common denominator");check(MathLesson.at(2,-2,-1).contains("Interior"),"Interior versus empty exterior");check(MathLesson.at(4,0,-2).contains("Vértice"),"Curved minimum");
  Map<String,Object> trace=MathLesson.trace(2,1000);check(((Number)trace.get("index")).intValue()==4&&trace.get("description").toString().contains("cerrado"),"Finite closed traversal");Map<String,Object> projection=MathLesson.project(5,0);check(((Number)projection.get("y")).doubleValue()==0,"Sine origin");Map<String,Object> plane=MathLesson.loadPlane(MathLesson.planeProject(6,-2,3));check(((Number)plane.get("plane")).intValue()==6&&((Number)plane.get("x")).doubleValue()==-2,"Plane state roundtrip");
  try{MathLesson.loadPlane("{\"schema\":\"formas-math-plane-v1\",\"plane\":0.5,\"x\":0,\"y\":0}");throw new AssertionError("Non-integer plane");}catch(IllegalArgumentException good){checks++;}
  check(MathLesson.cardinal(21000).equals("veintiún mil"),"Apocope");check(MathLesson.number("-12.05").equals("menos doce coma cero cinco"),"Signed decimal");check(new MathLesson("-3").tokens.get(0).equals("signo menos"),"Minus not lost");
  check(MathLesson.point(-2,3).x==220&&MathLesson.point(-2,3).y==105,"Cartesian y points upward");check(MathLesson.coordinate(-2,3).contains("segundo"),"Quadrant two");check(MathLesson.coordinate(0,0).contains("Origen"),"Origin");check(MathLesson.at(2,-3,-2).contains("Esquina"),"Square corner");check(MathLesson.at(3,3.5,1).contains("curvo"),"Circle curve");check(MathLesson.at(1,1,0.75).contains("recta"),"Straight segment");check(MathLesson.at(0,4,4).contains("vacío"),"Known empty area");
  for(int kind=0;kind<MathLesson.PLANES.length;kind++){Geometry g=MathLesson.plane(kind);check(g.shapes.size()>=3,"Plane geometry");for(Geometry.Shape sh:g.shapes)for(Geometry.Point p:sh.points)check(p.x>=100&&p.x<=500&&p.y>=25&&p.y<=425,"Plane bounds");check(!MathLesson.planeOverview(kind).isEmpty(),"Plane overview");}
  Map<?,?> genny=(Map<?,?>)Json.parse(new MathLesson("2x+3=11").genny());check(genny.containsKey("layers"),"External Genny script");try{MathLesson.point(Double.NaN,0);throw new AssertionError("NaN");}catch(IllegalArgumentException good){checks++;}
  MathLesson progressive=new MathLesson("(3+2)^2+7");check(progressive.development.size()==5,"Initial state, three changes and closure");check(progressive.development.get(1).contains("Antes:")&&progressive.development.get(1).contains("Ahora:"),"Whole expression retained around each change");check(progressive.development.get(2).contains("veinticinco")&&progressive.development.get(2).contains("siete"),"Unresolved context retained");check(progressive.development.get(3).contains("treinta y dos"),"Final transformation");check(new MathLesson("2x+3=11").development.toString().contains("Motivo: conservar la igualdad"),"Equation transformation reason");check(new MathLesson("1000-1").development.toString().contains("columna siguiente"),"Progressive borrowing");check(MathLesson.load(progressive.project()).development.equals(progressive.development),"Deterministic progression after reload");check(progressive.data().containsKey("development"),"Desktop progression protocol");
  System.out.println("PASS "+checks+" math checks: exact arithmetic, precedence, carry/borrow, division, linear equations, polynomials, trig units, rejected domains, serialization, progressive development and Cartesian geometry.");
 }
}
